// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(bytes calldata payload) public {
        vm.assume(payload.length < 10000);
        Reverter r = new Reverter();
        bool ok;
        try c.forward(address(r), payload) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "forward to a reverting callee must revert");
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
